source_rows as (
  select *
  from source_payload,
  jsonb_to_recordset(source_payload.data) as row(
    content_source_external_id text,
    topic_slug text,
    source_kind text,
    title text,
    file_name text,
    year_label text,
    locator_text text,
    metadata_json jsonb
  )
)
insert into public.content_sources (
  external_id,
  topic_id,
  source_kind,
  title,
  file_name,
  year_label,
  locator_text,
  metadata_json
)
select
  r.content_source_external_id,
  t.id,
  r.source_kind::public.content_source_kind,
  r.title,
  r.file_name,
  r.year_label,
  r.locator_text,
  coalesce(r.metadata_json, '{}'::jsonb)
from source_rows r
left join public.topics t on t.slug = r.topic_slug
on conflict (external_id) do update
set topic_id = excluded.topic_id,
    source_kind = excluded.source_kind,
    title = excluded.title,
    file_name = excluded.file_name,
    year_label = excluded.year_label,
    locator_text = excluded.locator_text,
    metadata_json = excluded.metadata_json;

