),
asset_rows as (
  select *
  from asset_payload,
  jsonb_to_recordset(asset_payload.data) as row(
    external_id text,
    asset_kind text,
    storage_bucket text,
    storage_path text,
    mime_type text,
    alt_text text,
    caption text,
    source_name text,
    source_locator text,
    metadata_json jsonb
  )
)
insert into public.question_assets (
  external_id,
  asset_kind,
  storage_bucket,
  storage_path,
  mime_type,
  alt_text,
  caption,
  source_name,
  source_locator,
  metadata_json
)
select
  r.external_id,
  r.asset_kind::public.question_asset_kind,
  r.storage_bucket,
  r.storage_path,
  r.mime_type,
  r.alt_text,
  r.caption,
  r.source_name,
  r.source_locator,
  coalesce(r.metadata_json, '{}'::jsonb)
from asset_rows r
on conflict (storage_path) do update
set asset_kind = excluded.asset_kind,
    storage_bucket = excluded.storage_bucket,
    mime_type = excluded.mime_type,
    alt_text = excluded.alt_text,
    caption = excluded.caption,
    source_name = excluded.source_name,
    source_locator = excluded.source_locator,
    metadata_json = excluded.metadata_json,
    external_id = coalesce(public.question_assets.external_id, excluded.external_id);

commit;
